<script setup lang="ts">
const { data, status } = await useWorkspace()
const stats = computed(() => [
  { label: 'Active experiments', value: data.value.runs.filter(r => r.status === 'running').length, sub: `${data.value.runs.filter(r => r.status === 'queued').length} waiting in queue`, icon: 'FlaskConical', color: 'orange' },
  { label: 'Connected compute', value: data.value.servers.filter(isOnline).length, sub: `${data.value.servers.length} registered workers`, icon: 'Cpu', color: 'green' },
  { label: 'Model library', value: data.value.models.length, sub: 'Ready for your next experiment', icon: 'Layers', color: 'purple' },
  { label: 'Datasets', value: data.value.datasets.length, sub: 'Local & Hugging Face sources', icon: 'Database', color: 'blue' },
])
const steps = computed(() => [
  { title: 'Connect your compute', description: 'Pair a worker on your GPU server.', to: '/servers', done: data.value.servers.some(isOnline), icon: 'Server' },
  { title: 'Bring your model & data', description: 'Register a model and training dataset.', to: '/datasets', done: data.value.models.length > 0 && data.value.datasets.length > 0, icon: 'Database' },
  { title: 'Run your first experiment', description: 'Configure, launch, and follow progress.', to: '/runs/new', done: data.value.runs.length > 0, icon: 'FlaskConical' },
])
</script>
