cription="Launch your first training run. Its progress, metrics, and checkpoints will appear here."><NuxtLink to="/runs/new" class="button secondary small"><AppIcon name="Plus" :size="15" />Create experiment</NuxtLink></EmptyState></section><section class="panel setup-panel"><div class="panel-heading"><div><h2>Make yourself at home</h2><p>{{ steps.filter(s => s.done).length }} of 3 steps complete</p></div><span class="setup-spark">✳</span></div><div class="setup-progress"><span :style="{ width: `${steps.filter(s => s.done).length / 3 * 100}%` }" /></div><NuxtLink v-for="(step, i) in steps" :key="step.title" :to="step.to" class="setup-step"><span class="step-index" :class="{ done: step.done }"><AppIcon v-if="step.done" name="Check" :size="15" /><template v-else>{{ i + 1 }}</template></span><div><strong>{{ step.title }}</strong><p>{{ step.description }}</p></div><AppIcon name="ChevronRight" :size="16" /></NuxtLink><div class="setup-note"><AppIcon name="ShieldCheck" :size="16" /><span>Your training runs on your infrastructure.</span></div></section></div><section class="recipe-strip"><span class="recipe-icon"><AppIcon name="AudioLines" :size="27" /></span><div><span class="eyebrow">FIRST TRAINING RECIPE</span><h3>Tamil speech recognition <span class="pill">Whisper + LoRA</span></h3><p>Built around your stt-tamil workflow, with Tamil and Latin-token evaluation.</p></div><NuxtLink to="/models" class="text-link">Explore models<AppIcon name="ArrowUpRight" :size="17" /></NuxtLink></section></template>
